mapper.select:
select fd.id as id, fd.case_id as caseId, fd.case_no as caseNo, fd.money as money, fd.retreat_time as retreatTime, fd.type as type, fd.state as state, ci.entrust_user_id as entrustUserId, ci.entrust_user_name as entrustUserName, ci.entrust_user_tel as entrustUserTel, ci.refound_remark as refoundRemark from law_fee_detail fd left join law_case_info ci on fd.case_id = ci.id where 1=1
and fd.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')
and ci.entrust_user_name like concat('%',#{entrustUserName,jdbcType=VARCHAR},'%')
and ci.entrust_user_tel like concat('%',#{entrustUserTel,jdbcType=VARCHAR},'%')
and type = #{type,jdbcType=INTEGER}
and state = #{state,jdbcType=INTEGER}
order by id desc limit #{pageIndex}, #{pageSize}

select count(1) from law_fee_detail fd left join law_case_info ci on fd.case_id = ci.id where 1=1
and fd.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')
and ci.entrust_user_name like concat('%',#{entrustUserName,jdbcType=VARCHAR},'%')
and ci.entrust_user_tel like concat('%',#{entrustUserTel,jdbcType=VARCHAR},'%')
and type = #{type,jdbcType=INTEGER}
and state = #{state,jdbcType=INTEGER}

select fd.id as id, fd.case_id as caseId, fd.case_no as caseNo, fd.money as money, fd.retreat_time as retreatTime, fd.type as type, fd.state as state,fd.arr_time as arrTime, fd.create_time as createTime, ci.entrust_user_id as entrustUserId, ci.entrust_user_name as entrustUserName, ci.entrust_user_tel as entrustUserTel, ci.refound_remark as refoundRemark from law_fee_detail fd left join law_case_info ci on fd.case_id = ci.id where 1 = 1
and fd.case_id = #{caseId,jdbcType=BIGINT}
and fd.type = #{type,jdbcType=BIGINT}
and fd.id = #{id,jdbcType=BIGINT}
limit 1
